pub fn report(r: Result<U, Ex>, idx: i64) {
    match r {
        Ok(u) => {
            println!("OK {} {}", idx, u.len());
            for c in u {
                println!("{}", c);
            }
        }
        Err(e) => {
            println!("ERR {} {}", idx, error_name(e.kind));
        }
    }
}

